validator:
function validate(input) {
  const [{ Data = [] }] = input;
  for (const [first, second] of Data) if (first === null || second === null) return 'Data rows may not contain null.';
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const rows = small ? Math.floor(rand() * 9) : 2000;
  const high = small ? 6 : 400;
  const Data = [];
  for (let i = 0; i < rows; i++) {
    // Small tables sometimes repeat a whole row, which the table allows.
    if (small && Data.length && rand() < 0.15) { Data.push(Data[Data.length - 1].slice()); continue; }
    Data.push([1 + Math.floor(rand() * high), 1 + Math.floor(rand() * high)]);
  }
  return [{ Data }];
}
